import React, { useEffect, useState } from 'react';
import { getProducts } from '../services/api';

function HomePage() {
    const [products, setProducts] = useState([]);

    useEffect(() => {
        async function fetchProducts() {
            try {
                const data = await getProducts();
                setProducts(data);
            } catch (err) {
                console.error('Error fetching products:', err);
            }
        }
        fetchProducts();
    }, []);

    return (
        <div className="bg-gray-50 min-h-screen">
            {/* Header */}
            <header className="bg-yellow-400 py-6 text-center">
                <h1 className="text-5xl font-bold text-gray-800">Welcome to MyShop</h1>
                <p className="text-gray-700 mt-2">Your one-stop shop for everything!</p>
            </header>

            {/* Product Grid */}
            <main className="container mx-auto px-4 py-8">
                <h2 className="text-2xl font-bold text-gray-800 mb-6">Featured Products</h2>
                <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-6">
                    {products.map((product) => (
                        <div
                            key={product.id}
                            className="bg-white border border-gray-200 rounded-lg shadow hover:shadow-lg p-4 flex flex-col items-center transition-transform transform hover:scale-105"
                        >
                            {/* Product Image */}
                            <div className="w-20 h-20 bg-gray-100 flex items-center justify-center rounded-md mb-3">
                                <img
                                    src={product.image}
                                    alt={product.name}
                                    className="w-full h-full object-contain"
                                />
                            </div>

                            {/* Product Details */}
                            <h3 className="font-semibold text-sm text-gray-800 text-center">{product.name}</h3>
                            <p className="text-gray-600 text-sm text-center mt-1">${product.price}</p>
                            <button className="mt-3 px-4 py-2 text-sm bg-yellow-400 text-gray-800 font-medium rounded hover:bg-yellow-300 transition-colors">
                                Add to Cart
                            </button>
                        </div>
                    ))}
                </div>
            </main>
        </div>
    );
}

export default HomePage;
